ock;\n  font-size: 1.5em;\n  font-weight: 700;\n  padding: 0.2em;\n}\ninput {\n  width: 90%;\n  margin: 5%;\n}\nh3 {\n  width: 100%;\n  font-size: 0.7em;\n  text-align: center;\n  margin-top: 0.5em;\n}\n</style>\n"],"sourceRoot":""}]);
